export const slots=['08:00','09:00','10:00','11:00','14:00','15:00','16:00','17:00'];
export const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
export function day(offset=0){const d=new Date(today()+'T12:00:00+05:30');d.setDate(d.getDate()+offset);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
export const seed=()=>({instructors:[{id:'i1',name:'Arjun Menon',phone:'Demo contact',specialty:'City driving',initials:'AM'},{id:'i2',name:'Priya Sharma',phone:'Demo contact',specialty:'Confidence & control',initials:'PS'}],vehicles:[{id:'v1',name:'Maruti Swift',reg:'KA 01 DX 2048',transmission:'Manual'},{id:'v2',name:'Hyundai i20',reg:'KA 03 DX 1024',transmission:'Automatic'}],bookings:[{id:'b1',student:'Jerrin',instructor:'i1',vehicle:'v1',date:day(1),time:'10:00',status:'confirmed',amount:800},{id:'b2',student:'Jerrin',instructor:'i1',vehicle:'v1',date:day(-2),time:'09:00',status:'completed',amount:800,score:8,notes:'Smooth gear changes. Practise checking mirrors before every turn.'},{id:'b3',student:'Jerrin',instructor:'i2',vehicle:'v2',date:day(-5),time:'11:00',status:'completed',amount:800,score:7,notes:'Good steering control. Keep a little more distance in traffic.'},{id:'b4',student:'Jerrin',instructor:'i1',vehicle:'v1',date:day(-8),time:'10:00',status:'completed',amount:800,score:6,notes:'A confident start. Work on a gentler clutch release.'}],payments:[{id:'p1',booking:'b1',amount:800,status:'paid'},{id:'p2',booking:'b2',amount:800,status:'paid'},{id:'p3',booking:'b3',amount:800,status:'paid'},{id:'p4',booking:'b4',amount:800,status:'paid'}]});
export function expire(s,now=Date.now()){for(const b of s.bookings)if(b.status==='pending'&&b.expiresAt<=now)b.status='expired'}
export function available(s,{date,time,instructor,vehicle,student='Jerrin'},now=Date.now()){expire(s,now);return !s.bookings.some(b=>b.date===date&&b.time===time&&['pending','confirmed','completed'].includes(b.status)&&(b.instructor===instructor||b.vehicle===vehicle||b.student===student))}
export function reserve(s,input,now=Date.now()){if(!/^\d{4}-\d{2}-\d{2}$/.test(input.date)||!slots.includes(input.time)||!Number.isFinite(new Date(input.date+'T'+input.time+':00+05:30').getTime())||new Date(input.date+'T'+input.time+':00+05:30').getTime()<=now)throw Error('Choose a future lesson time.');if(!s.instructors.some(i=>i.id===input.instructor)||!s.vehicles.some(v=>v.id===input.vehicle))throw Error('Choose an instructor and a vehicle.');if(!available(s,input,now))throw Error('This time is already reserved. Choose another slot.');const b={id:crypto.randomUUID(),student:'Jerrin',date:input.date,time:input.time,instructor:input.instructor,vehicle:input.vehicle,status:'pending',amount:800,expiresAt:now+600000};s.bookings.push(b);return b}
export function pay(s,id,success=true,now=Date.now()){expire(s,now);const b=s.bookings.find(b=>b.id===id);if(!b)throw Error('Booking not found.');if(b.status==='confirmed')return b;if(b.status!=='pending')throw Error('The reservation is no longer available. Book a new slot.');s.payments.push({id:crypto.randomUUID(),booking:id,amount:b.amount,status:success?'paid':'failed'});if(success)b.status='confirmed';return b}
export function cancel(s,id){const b=s.bookings.find(b=>b.id===id);if(!b||!['pending','confirmed'].includes(b.status))throw Error('This lesson cannot be cancelled.');b.status='cancelled';for(const p of s.payments)if(p.booking===id&&p.status==='paid')p.status='refunded';}
export function assess(s,id,instructor,score,notes,now=Date.now()){const b=s.bookings.find(b=>b.id===id);if(!b||b.instructor!==instructor||b.status!=='confirmed')throw Error('Only the assigned instructor can assess a confirmed lesson.');if(new Date(b.date+'T'+b.time+':00+05:30').getTime()+3600000>now)throw Error('Feedback is available after the lesson ends.');if(!Number.isInteger(score)||score<1||score>10||!notes.trim())throw Error('Enter a score from 1 to 10 and lesson notes.');b.score=score;b.notes=notes.trim();b.status='completed';return b}
